import gaps from './gaps.json'
import type { SpecPageData } from './types'

// The 124 pages of "Every feature, drawn", as the canvas draws them (generated by scripts/spec-from-canvas.mjs).
// Their rows hold the canvas's invented titles: they are for looking at beside the pictures (/design/gaps), never
// shown as someone's own data. A real page builds its spec from real data (see specs/).
export const GAP_PAGES = gaps as SpecPageData[]
export const gapPage = (key: string) => GAP_PAGES.find((p) => p.key === key)
